import re


def ContentA(str0):
    return bool(re.search('[a-z]', str0))

if True:
    rem = '\b'
    ChModel = re.compile(u'[\u4e00-\u9fa5]')
    while rem != 'q':
        text = input("input--")
        match = ChModel.search(text)
        if match:
            res = str(text.encode("unicode_escape"))
            res = res.replace('\\\\', '\\')
            res = res[1:]
            print(res)
        else:
            if ContentA(str(text)) and not str(text).__contains__('\\u'):
                u = str(text)
                u = u.replace('\\', '/')
                print(u)
            else:
                u = str(text.encode('latin-1').decode('unicode_escape'))
                print(u)

